            <option [value]="g" [selected]="g === bulkGradeInput()">{{ g }}</option>
          }
        </select>
        <label for="bulk-grade-from">from</label>
        <input
          type="date"
          id="bulk-grade-from"
          data-testid="bulk-grade-from"
          [value]="bulkGradeFrom()"
          (input)="bulkGradeFrom.set($any($event.target).value); bulkGradeError.set(null)"
        />
        <button type="submit" data-testid="bulk-grade-apply">Give grade</button>
        @if (bulkGraded() !== null) {
          <p>Changed <strong data-testid="bulk-graded">{{ bulkGraded() }}</strong></p>
        }
        @if (bulkGradeError(); as err) {
          <p role="alert" data-testid="person-error">{{ err }}</p>
        }
      </form>
      <p>Claimed in total <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
      <p>Due in total <strong data-testid="rollup-due-total">{{ dueTotal() }}</strong></p>
      <p>Settled in total <strong data-testid="rollup-settled-total">{{ money(settledOpenTotals().settled) }}</strong></p>
      <p>Open in total <strong data-testid="rollup-open-total">{{ money(settledOpenTotals().open) }}</strong></p>
      <p>Overdue claims <strong data-testid="rollup-overdue-count">{{ overdueTotals().count }}</strong></p>
      <p>Overdue in total <strong data-testid="rollup-overdue-total">{{ money(overdueTotals().cents) }}</strong></p>
      @if (tagTotals().length > 0) {
        <table aria-label="Due by tag">
          <thead>
            <tr>
              <th scope="col">Tag</th>
              <th scope="col">Due</th>
            </tr>
          </thead>
          <tbody>
            @for (t of tagTotals(); track t.tag) {
              <tr>
                <th scope="row">{{ t.tag }}</th>
                <td [attr.data-testid]="'tag-' + t.tag + '-due-total'">{{ money(t.cents) }}</td>
              </tr>
            }
          </tbody>
        </table>
      }
      <app-summary [grades]="gradeSummary()" [periods]="periodSummary()" [statuses]="statusSummary()" [voidReasons]="voidReasonSummary()" />
      <table data-testid="people-list">
        <thead>
          <tr>
            <th scope="col"><span class="visually-hidden">Select</span></th>

